B.adF=new A.dE([B.cE,"Koperen Nacht Tripel","Goudkoper van kleur met een romige schuimkraag. Kruidig, tonen van karamel en een warme afdronk. Gevaarlijk doordrinkbaar.",u.P,"Sanne",4.5])
B.cX=new A.jl(1,"tip")
B.adY=new A.dE([B.cX,"Spoel je glas eerst koud om","Een koud gespoeld glas zorgt voor een mooiere schuimkraag en voorkomt dat je bier te snel opwarmt.",null,"BierKompas",null])
B.adB=new A.dE([B.cF,"Waarom heet het trappist?",'Een bier mag het logo "Authentic Trappist Product" alleen dragen als het onder toezicht van monniken binnen een trappistenabdij wordt gebrouwen.',null,null,null])
B.adT=new A.dE([B.cE,"Amber Kompas IPA","Fris bitter met grapefruit en dennen, maar de moutbasis houdt alles mooi in balans. Een perfect terrasbier.",null,"Joris",4])
B.adD=new A.dE([B.cX,"Schenk schuin, eindig recht","Houd het glas schuin tijdens het inschenken en zet het halverwege rechtop. Zo krijg je een kraag van ongeveer twee vingers.",null,"BierKompas",null])
B.adJ=new A.dE([B.cF,"Bock komt uit Einbeck","De naam bockbier is waarschijnlijk een verbastering van Einbeck, een Duitse stad die in de middeleeuwen bekend was om zijn sterke bier.",null,null,null])
B.adK=new A.dE([B.cE,"Donkere Molen Stout","Koffie, pure chocolade en een fluweelzachte mondvulling. Laat hem iets opwarmen, dan komt de vanille los.",null,"Fatima",4.5])
B.ae0=new A.dE([B.cX,"Niet elk bier hoort ijskoud","Pils smaakt het best rond 3 tot 5 graden, maar dubbels, tripels en stouts komen pas echt tot hun recht rond 8 tot 12 graden.",null,"BierKompas",null])
B.ae_=new A.dE([B.cF,"Hop is familie van hennep","Hop en hennep horen allebei bij de plantenfamilie Cannabaceae. Hop geeft bier bitterheid, aroma en een langere houdbaarheid.",null,null,null])
B.adS=new A.dE([B.cE,"Zomerhaven Witbier","Troebel, met citrus en koriander. Iets te zoet naar mijn smaak, maar heerlijk als het buiten 25 graden is.",u.g,"Daan",3.5])
B.adP=new A.dE([B.cX,"Bewaar flessen rechtop","Rechtop, koel en donker bewaard blijft bier langer goed. Licht kan zorgen voor een onaangename, muffe smaak.",null,"BierKompas",null])
B.adL=new A.dE([B.cF,"Spontane vergisting","Lambiek wordt spontaan vergist met wilde gisten en bacteri\xebn uit de lucht, traditioneel in de regio rond Brussel.","https://lh3.googleusercontent.com/aida-public/AB6AXuDknuVmwDTa5jB4wik1JsFZcg3HGHEguJ8tKYPIGvMOxeMgWo55nIZ92P0i_iTaZK5gCmhHDfSDDGd8HAgulU_Nt_waa4YIg1QNZCDQnGG9J70xbRh0XNaZFjxojqCPad3s7iiMSHzET5kRpj3GQcD9-hE4MuWtaKdUaP4Wkk6S1kxJhurPAITpPBmmuOIAnJ0_rU6wNjOB6JuYsppLKZZ370oFdfVTbvOpttwPVmC3aU02O1rJkSR2",null,null])
B.adG=new A.dE([B.cE,"Oude Sluis Dubbel","Rozijnen, bruine suiker en een vleugje drop. Een klassieke dubbel zonder poespas.",null,"Emma",4])
B.adM=new A.dE([B.cX,"Stout bij chocolade","De geroosterde tonen van een stout versterken een chocoladedessert. Probeer het eens met een brownie.",null,"BierKompas",null])
B.adX=new A.dE([B.cF,"Gueuze is een blend","Gueuze ontstaat door jonge en oude lambiek te mengen en op fles na te laten gisten. Daardoor krijgt het zijn bruisende, zure karakter.",null,null,null])
B.adI=new A.dE([B.cE,"Veldkers Saison","Droog, peperig en licht fruitig. Elke slok maakt dorst naar de volgende.",null,"Luuk",4.5])
B.adZ=new A.dE([B.cX,"Witbier bij vis en mosselen","De citrus- en korianderaroma's van witbier passen perfect bij vis, mosselen en frisse salades.",null,"BierKompas",null])
B.adU=new A.dE([B.cF,"Het Reinheitsgebot","In 1516 bepaalde Beieren dat bier alleen van water, gerst en hop gemaakt mocht worden. Gist werd pas later ontdekt en toegevoegd.",null,null,null])
B.adW=new A.dE([B.cE,"Koperen Nacht Blond","Honingzoet begin en een licht bittere finish. Toegankelijk, maar het mist wat karakter.",null,"Noor",3])
B.adA=new A.dE([B.cX,"Proef van licht naar zwaar","Begin een proeverij met lichte, frisse bieren en werk toe naar zware en zure bieren, zodat je smaakpapillen niet overweldigd raken.",null,"BierKompas",null])
B.adE=new A.dE([B.cF,"Donker is niet sterker","De kleur van bier komt van de mout, niet van het alcoholpercentage. Een donkere stout kan lichter zijn dan een blonde tripel.",null,null,null])
B.adQ=new A.dE([B.cE,"Winterlicht Bock","Karamel en geroosterd brood: precies wat je wilt als het buiten stormt.",null,"Milan",4])
B.adH=new A.dE([B.cX,"Ruik voordat je proeft","Een groot deel van wat je proeft is eigenlijk geur. Houd het glas even onder je neus voor de eerste slok.",null,"BierKompas",null])
B.adz=new A.dE([B.cF,"K\xf6lsch is een beschermde naam","Volgens de K\xf6lsch-Konvention mag alleen bier dat in en rond Keulen wordt gebrouwen zich K\xf6lsch noemen.",null,null,null])
B.ae1=new A.dE([B.cE,"Havenmeester Pale Ale","Mooi helder, bloemige hop en een droge afdronk. Een echte allrounder.",u.H,"Lotte",4])
B.adN=new A.dE([B.cX,"Kies het juiste glas","Een tulpglas houdt het aroma van speciaalbier vast; een smal pilsglas houdt het koolzuur langer vast.",null,"BierKompas",null])
B.adC=new A.dE([B.cF,"Witbier kwam terug dankzij een melkboer","Nadat witbier in Belgi\xeb was verdwenen, bracht melkboer Pierre Celis de stijl in 1966 terug in Hoegaarden.",null,null,null])
B.adO=new A.dE([B.cE,"Kelderzuur Kriek","Zuur, kersen en een tikje amandel. Niet voor iedereen, wel voor mij.",null,"Yara",5])
B.adR=new A.dE([B.cX,"Laat de gist in de fles","Bij bieren met nagisting op fles zit gistbezinksel onderin. Schenk rustig en laat het laatste bodempje staan.",null,"BierKompas",null])
B.adV=new A.dE([B.cF,"De kraag doet ertoe","De schuimkraag houdt aroma's vast, zodat je neus meeproeft. Zonder kraag verliest bier sneller zijn geur.",null,null,null])
